import 'package:cloud_firestore/cloud_firestore.dart';
import 'package:firebase_auth/firebase_auth.dart';
class MiniAppStateService { final FirebaseFirestore db; final FirebaseAuth auth; MiniAppStateService({FirebaseFirestore? firestore,FirebaseAuth? firebaseAuth}):db=firestore??FirebaseFirestore.instance,auth=firebaseAuth??FirebaseAuth.instance; DocumentReference<Map<String,dynamic>> ref(String app)=>db.collection('users').doc(auth.currentUser!.uid).collection('miniApps').doc(app); Future<void> save(String app,Map<String,dynamic> state)=>ref(app).set({'state':state,'updatedAt':FieldValue.serverTimestamp()},SetOptions(merge:true)); Future<Map<String,dynamic>?> load(String app) async {final d=await ref(app).get();final s=d.data()?['state'];return s is Map?Map<String,dynamic>.from(s):null;} }